using BaseLib.Extensions;
using MegaCrit.Sts2.Core.Commands;
using MegaCrit.Sts2.Core.Entities.Cards;
using MegaCrit.Sts2.Core.GameActions.Multiplayer;
using ShionTheBruiser.ShionTheBruiserCode.Cards;
using ShionTheBruiser.ShionTheBruiserCode.Powers;

namespace ShionTheBruiser.ShionTheBruiserCode.Critical;

public abstract class CritContributorCard(int cost, CardType type, CardRarity rarity, TargetType target) :
    ShionTheBruiserCard(cost, type, rarity, target)
{
    public override async Task BeforeCombatStart()
    {
        if (Owner != null && !Owner.HasPower<ShionCritTrackerPower>())
        {
            await PowerCmd.Apply<ShionCritTrackerPower>(
                new ThrowingPlayerChoiceContext(),
                Owner.Creature,
                amount: 1m,
                applier: Owner.Creature,
                cardSource: null);
        }
    }
}

using BaseLib.Extensions;
using MegaCrit.Sts2.Core.Commands;
using MegaCrit.Sts2.Core.Entities.Cards;
using MegaCrit.Sts2.Core.GameActions.Multiplayer;
using ShionTheBruiser.ShionTheBruiserCode.Cards;
using ShionTheBruiser.ShionTheBruiserCode.Powers;

namespace ShionTheBruiser.ShionTheBruiserCode.Critical;

public abstract class CritContributorCard(int cost, CardType type, CardRarity rarity, TargetType target) :
    ShionTheBruiserCard(cost, type, rarity, target)
{
    public override async Task BeforeCombatStart()
    {
        MainFile.Logger.Info($"[CritContributorCard] BeforeCombatStart fired on {GetType().Name}. Owner={(Owner == null ? "NULL" : Owner.GetType().Name)}");

        if (Owner == null)
        {
            MainFile.Logger.Info($"[CritContributorCard] Owner is null — tracker power NOT applied.");
            return;
        }

        bool alreadyHas = Owner.HasPower<ShionCritTrackerPower>();
        MainFile.Logger.Info($"[CritContributorCard] Owner already has ShionCritTrackerPower: {alreadyHas}");

        if (!alreadyHas)
        {
            MainFile.Logger.Info($"[CritContributorCard] Applying ShionCritTrackerPower to {Owner.Creature?.GetType().Name ?? "null creature"}...");
            await PowerCmd.Apply<ShionCritTrackerPower>(
                new ThrowingPlayerChoiceContext(),
                Owner.Creature,
                amount: 1m,
                applier: Owner.Creature,
                cardSource: null);
            MainFile.Logger.Info($"[CritContributorCard] ShionCritTrackerPower applied.");
        }
    }
}

using Godot;
using MegaCrit.Sts2.Core.Combat;
using MegaCrit.Sts2.Core.Models;
using ShionTheBruiser.ShionTheBruiserCode.Helper;

namespace ShionTheBruiser.ShionTheBruiserCode.Critical;

/// <summary>
/// Central state manager for Shion's Critical Damage mechanic.
/// All state is static because STS2's game logic is single-threaded.
/// The <see cref="Relics.ShionCritTrackerRelic"/> drives this class via combat hooks.
/// </summary>
public static class ShionCritSystem
{
    /// <summary>
    /// True when the whole-attack critical roll succeeded for the current attack.
    /// If true, every hit of the attack is a critical hit regardless of the per-hit roll.
    /// </summary>
    private static bool _critAttack;

    /// <summary>
    /// True when the current individual hit is a critical hit.
    /// Set inside <see cref="EnsureHitRolled"/> and read by the tracker relic's
    /// <c>ModifyDamageMultiplicative</c> and <c>AfterDamageGiven</c> overrides.
    /// </summary>
    private static bool _currentHitIsCrit;

    /// <summary>
    /// Guard flag: true once a per-hit crit roll has been performed for the current hit.
    /// Prevents re-rolling when multiple targets are hit by the same attack call,
    /// or when <see cref="EnsureHitRolled"/> is called more than once.
    /// Reset by <see cref="EndHit"/> between hits.
    /// </summary>
    private static bool _hitCritRolled;

    /// <summary>Whether the hit currently being resolved is a critical hit.</summary>
    public static bool CurrentHitIsCrit => _currentHitIsCrit;

    /// <summary>
    /// Called once at the beginning of each attack (<c>BeforeAttack</c> hook).
    /// Performs the whole-attack crit roll and resets per-hit state.
    /// </summary>
    /// <param name="cs">Current combat state used to iterate hook listeners.</param>
    /// <param name="card">
    /// The card that started the attack, or <c>null</c> for card-less attacks.
    /// Passed to contributor interfaces so they can filter by card type if needed.
    /// </param>
    public static void StartAttack(ICombatState cs, CardModel? card)
    {
        decimal attackRate = card != null
            ? ShionHooksHelper.CalculateCritAttackRate(cs, card)
            : 0m;
        _critAttack = (decimal)GD.Randf() < attackRate;
        _currentHitIsCrit = false;
        _hitCritRolled = false;
    }

    /// <summary>
    /// Performs a per-hit crit roll if one has not already been performed for this hit.
    /// Idempotent: subsequent calls within the same hit are no-ops (guarded by
    /// <see cref="_hitCritRolled"/>).
    /// Called inside <c>ModifyDamageMultiplicative</c> so the roll happens at the
    /// moment the damage is calculated, which also covers neutral cards (which do
    /// not inject a <c>BeforeDamage</c> callback).
    /// </summary>
    public static void EnsureHitRolled(ICombatState cs, CardModel? card)
    {
        if (_hitCritRolled) return;
        decimal hitRate = card != null
            ? ShionHooksHelper.CalculateCritHitRate(cs, card)
            : 0m;
        _currentHitIsCrit = _critAttack || (decimal)GD.Randf() < hitRate;
        _hitCritRolled = true;
    }

    /// <summary>
    /// Signals that the current individual hit has been fully resolved.
    /// Resets the per-hit roll guard so the next hit gets an independent roll.
    /// Called in <c>AfterDamageGiven</c> by the tracker relic.
    /// Does NOT reset <see cref="_currentHitIsCrit"/> — that value remains valid
    /// until the next roll (needed by <c>AfterDamageGiven</c> for subsequent AOE
    /// targets that were damaged in the same <c>CreatureCmd.Damage</c> call).
    /// </summary>
    public static void EndHit() => _hitCritRolled = false;

    /// <summary>
    /// Fully resets all crit state after an attack has finished.
    /// Called in <c>AfterAttack</c> by the tracker relic.
    /// </summary>
    public static void EndAttack()
    {
        _critAttack = false;
        _currentHitIsCrit = false;
        _hitCritRolled = false;
    }
}

using Godot;
using MegaCrit.Sts2.Core.Combat;
using MegaCrit.Sts2.Core.Models;
using ShionTheBruiser.ShionTheBruiserCode.Helper;

namespace ShionTheBruiser.ShionTheBruiserCode.Critical;

/// <summary>
/// Central state manager for Shion's Critical Damage mechanic.
/// All state is static because STS2's game logic is single-threaded.
/// The <see cref="Relics.ShionCritTrackerRelic"/> drives this class via combat hooks.
/// </summary>
public static class ShionCritSystem
{
    /// <summary>
    /// True when the whole-attack critical roll succeeded for the current attack.
    /// If true, every hit of the attack is a critical hit regardless of the per-hit roll.
    /// </summary>
    private static bool _critAttack;

    /// <summary>
    /// True when the current individual hit is a critical hit.
    /// Set inside <see cref="EnsureHitRolled"/> and read by the tracker relic's
    /// <c>ModifyDamageMultiplicative</c> and <c>AfterDamageGiven</c> overrides.
    /// </summary>
    private static bool _currentHitIsCrit;

    /// <summary>
    /// Guard flag: true once a per-hit crit roll has been performed for the current hit.
    /// Prevents re-rolling when multiple targets are hit by the same attack call,
    /// or when <see cref="EnsureHitRolled"/> is called more than once.
    /// Reset by <see cref="EndHit"/> between hits.
    /// </summary>
    private static bool _hitCritRolled;

    /// <summary>Whether the hit currently being resolved is a critical hit.</summary>
    public static bool CurrentHitIsCrit => _currentHitIsCrit;

    /// <summary>
    /// Called once at the beginning of each attack (<c>BeforeAttack</c> hook).
    /// Performs the whole-attack crit roll and resets per-hit state.
    /// </summary>
    /// <param name="cs">Current combat state used to iterate hook listeners.</param>
    /// <param name="card">
    /// The card that started the attack, or <c>null</c> for card-less attacks.
    /// Passed to contributor interfaces so they can filter by card type if needed.
    /// </param>
    public static void StartAttack(ICombatState cs, CardModel? card)
    {
        decimal attackRate = card != null
            ? ShionHooksHelper.CalculateCritAttackRate(cs, card)
            : 0m;
        float roll = GD.Randf();
        _critAttack = (decimal)roll < attackRate;
        _currentHitIsCrit = false;
        _hitCritRolled = false;
        MainFile.Logger.Info($"[ShionCritSystem] StartAttack — card={card?.GetType().Name ?? "null"}, attackRate={attackRate:P0}, roll={roll:F3}, _critAttack={_critAttack}");
    }

    /// <summary>
    /// Performs a per-hit crit roll if one has not already been performed for this hit.
    /// Idempotent: subsequent calls within the same hit are no-ops (guarded by
    /// <see cref="_hitCritRolled"/>).
    /// Called inside <c>ModifyDamageMultiplicative</c> so the roll happens at the
    /// moment the damage is calculated, which also covers neutral cards (which do
    /// not inject a <c>BeforeDamage</c> callback).
    /// </summary>
    public static void EnsureHitRolled(ICombatState cs, CardModel? card)
    {
        if (_hitCritRolled) return;
        decimal hitRate = card != null
            ? ShionHooksHelper.CalculateCritHitRate(cs, card)
            : 0m;
        float roll = GD.Randf();
        _currentHitIsCrit = _critAttack || (decimal)roll < hitRate;
        _hitCritRolled = true;
        MainFile.Logger.Info($"[ShionCritSystem] EnsureHitRolled — card={card?.GetType().Name ?? "null"}, hitRate={hitRate:P0}, roll={roll:F3}, _critAttack={_critAttack}, _currentHitIsCrit={_currentHitIsCrit}");
    }

    /// <summary>
    /// Signals that the current individual hit has been fully resolved.
    /// Resets the per-hit roll guard so the next hit gets an independent roll.
    /// Called in <c>AfterDamageGiven</c> by the tracker relic.
    /// Does NOT reset <see cref="_currentHitIsCrit"/> — that value remains valid
    /// until the next roll (needed by <c>AfterDamageGiven</c> for subsequent AOE
    /// targets that were damaged in the same <c>CreatureCmd.Damage</c> call).
    /// </summary>
    public static void EndHit() => _hitCritRolled = false;

    /// <summary>
    /// Fully resets all crit state after an attack has finished.
    /// Called in <c>AfterAttack</c> by the tracker relic.
    /// </summary>
    public static void EndAttack()
    {
        _critAttack = false;
        _currentHitIsCrit = false;
        _hitCritRolled = false;
    }
}

using MegaCrit.Sts2.Core.Combat;
using MegaCrit.Sts2.Core.Models;
using ShionTheBruiser.ShionTheBruiserCode.Critical;

namespace ShionTheBruiser.ShionTheBruiserCode.Helper;

public static class ShionHooksHelper
{
    /// <summary>
    /// Calculates the effective per-hit critical chance for the given card.
    /// Sums all <see cref="ICritHitRateContributor"/> bonuses from current combat hook
    /// listeners, then clamps the result to be at least the highest floor set by any
    /// <see cref="IMinCritHitRateContributor"/>.
    /// </summary>
    public static decimal CalculateCritHitRate(ICombatState combatState, CardModel? card)
    {
        // Exclude the source card from the listener query — it is checked directly below.
        // Cards often leave the hook-listener set before ModifyDamageMultiplicative fires
        // (they're no longer in the hand), so we can't rely on IterateHookListeners() alone.
        // The explicit exclusion also prevents double-counting on the rare occasion the card
        // IS still in the listener set.
        decimal rate = combatState.IterateHookListeners()
            .Where(l => l != card)
            .OfType<ICritHitRateContributor>()
            .Sum(c => c.GetCritHitRateBonus(card));

        if (card is ICritHitRateContributor cardHitContributor)
            rate += cardHitContributor.GetCritHitRateBonus(card);

        decimal minRate = combatState.IterateHookListeners()
            .Where(l => l != card)
            .OfType<IMinCritHitRateContributor>()
            .Select(c => c.GetMinCritHitRate(card))
            .DefaultIfEmpty(0m)
            .Max();

        if (card is IMinCritHitRateContributor cardMinHitContributor)
            minRate = Math.Max(minRate, cardMinHitContributor.GetMinCritHitRate(card));

        return Math.Max(rate, minRate);
    }

    /// <summary>
    /// Calculates the effective whole-attack critical chance for the given card.
    /// If this rolls true, every hit of the attack will be critical regardless of the
    /// per-hit roll. Sums all <see cref="ICritAttackRateContributor"/> bonuses, then
    /// clamps to the floor set by <see cref="IMinCritAttackRateContributor"/> contributors.
    /// </summary>
    public static decimal CalculateCritAttackRate(ICombatState combatState, CardModel? card)
    {
        // Same direct-card logic as CalculateCritHitRate — see comments there.
        decimal rate = combatState.IterateHookListeners()
            .Where(l => l != card)
            .OfType<ICritAttackRateContributor>()
            .Sum(c => c.GetCritAttackRateBonus(card));

        if (card is ICritAttackRateContributor cardAttackContributor)
            rate += cardAttackContributor.GetCritAttackRateBonus(card);

        decimal minRate = combatState.IterateHookListeners()
            .Where(l => l != card)
            .OfType<IMinCritAttackRateContributor>()
            .Select(c => c.GetMinCritAttackRate(card))
            .DefaultIfEmpty(0m)
            .Max();

        if (card is IMinCritAttackRateContributor cardMinAttackContributor)
            minRate = Math.Max(minRate, cardMinAttackContributor.GetMinCritAttackRate(card));

        return Math.Max(rate, minRate);
    }

    /// <summary>
    /// Returns only the minimum floor for per-hit crit chance, without adding any
    /// contributor bonuses. Useful when you need to inspect the floor in isolation.
    /// </summary>
    public static decimal CalculateMinCritHitRate(ICombatState combatState, CardModel card)
    {
        return combatState.IterateHookListeners()
            .OfType<IMinCritHitRateContributor>()
            .Select(c => c.GetMinCritHitRate(card))
            .DefaultIfEmpty(0m)
            .Max();
    }

    /// <summary>
    /// Returns only the minimum floor for whole-attack crit chance, without adding any
    /// contributor bonuses. Useful when you need to inspect the floor in isolation.
    /// </summary>
    public static decimal CalculateMinCritAttackRate(ICombatState combatState, CardModel card)
    {
        return combatState.IterateHookListeners()
            .OfType<IMinCritAttackRateContributor>()
            .Select(c => c.GetMinCritAttackRate(card))
            .DefaultIfEmpty(0m)
            .Max();
    }
}

using MegaCrit.Sts2.Core.Combat;
using MegaCrit.Sts2.Core.Models;
using ShionTheBruiser.ShionTheBruiserCode.Critical;

namespace ShionTheBruiser.ShionTheBruiserCode.Helper;

public static class ShionHooksHelper
{
    /// <summary>
    /// Calculates the effective per-hit critical chance for the given card.
    /// Sums all <see cref="ICritHitRateContributor"/> bonuses from current combat hook
    /// listeners, then clamps the result to be at least the highest floor set by any
    /// <see cref="IMinCritHitRateContributor"/>.
    /// </summary>
    public static decimal CalculateCritHitRate(ICombatState combatState, CardModel? card)
    {
        MainFile.Logger.Info($"[ShionHooksHelper] CalculateCritHitRate — card={card?.GetType().Name ?? "null"}");

        decimal rate = 0m;
        foreach (var l in combatState.IterateHookListeners().Where(l => l != card).OfType<ICritHitRateContributor>())
        {
            decimal bonus = l.GetCritHitRateBonus(card);
            MainFile.Logger.Info($"[ShionHooksHelper]   listener contributor {l.GetType().Name} → hitRateBonus={bonus:P0}");
            rate += bonus;
        }

        if (card is ICritHitRateContributor cardHitContributor)
        {
            decimal bonus = cardHitContributor.GetCritHitRateBonus(card);
            MainFile.Logger.Info($"[ShionHooksHelper]   direct-card contributor {card.GetType().Name} → hitRateBonus={bonus:P0}");
            rate += bonus;
        }
        else
        {
            MainFile.Logger.Info($"[ShionHooksHelper]   card {card?.GetType().Name ?? "null"} does NOT implement ICritHitRateContributor");
        }

        decimal minRate = 0m;
        foreach (var l in combatState.IterateHookListeners().Where(l => l != card).OfType<IMinCritHitRateContributor>())
        {
            decimal floor = l.GetMinCritHitRate(card);
            MainFile.Logger.Info($"[ShionHooksHelper]   listener minHit {l.GetType().Name} → floor={floor:P0}");
            minRate = Math.Max(minRate, floor);
        }

        if (card is IMinCritHitRateContributor cardMinHitContributor)
        {
            decimal floor = cardMinHitContributor.GetMinCritHitRate(card);
            MainFile.Logger.Info($"[ShionHooksHelper]   direct-card minHit {card.GetType().Name} → floor={floor:P0}");
            minRate = Math.Max(minRate, floor);
        }

        decimal result = Math.Max(rate, minRate);
        MainFile.Logger.Info($"[ShionHooksHelper] CalculateCritHitRate result: rate={rate:P0}, minRate={minRate:P0}, final={result:P0}");
        return result;
    }

    /// <summary>
    /// Calculates the effective whole-attack critical chance for the given card.
    /// If this rolls true, every hit of the attack will be critical regardless of the
    /// per-hit roll. Sums all <see cref="ICritAttackRateContributor"/> bonuses, then
    /// clamps to the floor set by <see cref="IMinCritAttackRateContributor"/> contributors.
    /// </summary>
    public static decimal CalculateCritAttackRate(ICombatState combatState, CardModel? card)
    {
        MainFile.Logger.Info($"[ShionHooksHelper] CalculateCritAttackRate — card={card?.GetType().Name ?? "null"}");

        decimal rate = 0m;
        foreach (var l in combatState.IterateHookListeners().Where(l => l != card).OfType<ICritAttackRateContributor>())
        {
            decimal bonus = l.GetCritAttackRateBonus(card);
            MainFile.Logger.Info($"[ShionHooksHelper]   listener contributor {l.GetType().Name} → attackRateBonus={bonus:P0}");
            rate += bonus;
        }

        if (card is ICritAttackRateContributor cardAttackContributor)
        {
            decimal bonus = cardAttackContributor.GetCritAttackRateBonus(card);
            MainFile.Logger.Info($"[ShionHooksHelper]   direct-card contributor {card.GetType().Name} → attackRateBonus={bonus:P0}");
            rate += bonus;
        }
        else
        {
            MainFile.Logger.Info($"[ShionHooksHelper]   card {card?.GetType().Name ?? "null"} does NOT implement ICritAttackRateContributor");
        }

        decimal minRate = 0m;
        foreach (var l in combatState.IterateHookListeners().Where(l => l != card).OfType<IMinCritAttackRateContributor>())
        {
            decimal floor = l.GetMinCritAttackRate(card);
            MainFile.Logger.Info($"[ShionHooksHelper]   listener minAttack {l.GetType().Name} → floor={floor:P0}");
            minRate = Math.Max(minRate, floor);
        }

        if (card is IMinCritAttackRateContributor cardMinAttackContributor)
        {
            decimal floor = cardMinAttackContributor.GetMinCritAttackRate(card);
            MainFile.Logger.Info($"[ShionHooksHelper]   direct-card minAttack {card.GetType().Name} → floor={floor:P0}");
            minRate = Math.Max(minRate, floor);
        }

        decimal result = Math.Max(rate, minRate);
        MainFile.Logger.Info($"[ShionHooksHelper] CalculateCritAttackRate result: rate={rate:P0}, minRate={minRate:P0}, final={result:P0}");
        return result;
    }

    /// <summary>
    /// Returns only the minimum floor for per-hit crit chance, without adding any
    /// contributor bonuses. Useful when you need to inspect the floor in isolation.
    /// </summary>
    public static decimal CalculateMinCritHitRate(ICombatState combatState, CardModel card)
    {
        return combatState.IterateHookListeners()
            .OfType<IMinCritHitRateContributor>()
            .Select(c => c.GetMinCritHitRate(card))
            .DefaultIfEmpty(0m)
            .Max();
    }

    /// <summary>
    /// Returns only the minimum floor for whole-attack crit chance, without adding any
    /// contributor bonuses. Useful when you need to inspect the floor in isolation.
    /// </summary>
    public static decimal CalculateMinCritAttackRate(ICombatState combatState, CardModel card)
    {
        return combatState.IterateHookListeners()
            .OfType<IMinCritAttackRateContributor>()
            .Select(c => c.GetMinCritAttackRate(card))
            .DefaultIfEmpty(0m)
            .Max();
    }
}

using MegaCrit.Sts2.Core.Commands.Builders;
using MegaCrit.Sts2.Core.Entities.Creatures;
using MegaCrit.Sts2.Core.GameActions.Multiplayer;
using MegaCrit.Sts2.Core.Localization.DynamicVars;
using MegaCrit.Sts2.Core.Models;
using MegaCrit.Sts2.Core.ValueProps;
using ShionTheBruiser.ShionTheBruiserCode.Critical;
using ShionTheBruiser.ShionTheBruiserCode.Variables;

namespace ShionTheBruiser.ShionTheBruiserCode.Powers;

/// <summary>
/// Internal tracker power that drives Shion's Critical Damage system.
///
/// This power is applied automatically to any creature whose combat-active
/// models include at least one <see cref="Critical.ICritHitRateContributor"/>,
/// <see cref="Critical.ICritAttackRateContributor"/>, or the minimum-rate
/// equivalents. It is applied via
/// <see cref="Critical.CritContributorPower.BeforeCombatStart"/> or
/// <see cref="Critical.CritContributorRelic.BeforeCombatStart"/>, so it
/// activates for <em>any</em> character that holds a crit contributor —
/// not just Shion.
///
/// Because it is a <see cref="MegaCrit.Sts2.Core.Entities.Powers.PowerStackType.Single"/>
/// power, repeated application is a no-op; exactly one instance exists per
/// creature per combat.
/// </summary>
public class ShionCritTrackerPower : ShionTheBruiserPower
{
    public override MegaCrit.Sts2.Core.Entities.Powers.PowerType Type =>
        MegaCrit.Sts2.Core.Entities.Powers.PowerType.Buff;

    public override MegaCrit.Sts2.Core.Entities.Powers.PowerStackType StackType =>
        MegaCrit.Sts2.Core.Entities.Powers.PowerStackType.Single;

    // ── DynamicVars ───────────────────────────────────────────────────────────

    /// <summary>
    /// Exposes the live crit rates as lazily-computed tokens for the smart description.
    /// <c>{HitRate}</c>    → per-hit critical chance as a whole integer percentage.
    /// <c>{AttackRate}</c> → whole-attack critical chance as a whole integer percentage.
    /// Both include the minimum-rate floor and are computed fresh on every hover-tip render.
    /// </summary>
    protected override IEnumerable<DynamicVar> CanonicalVars =>
    [
        new CritRateDisplayVar(isAttackRate: false),  // {HitRate}
        new CritRateDisplayVar(isAttackRate: true),   // {AttackRate}
    ];

    // ── Combat hooks ─────────────────────────────────────────────────────────

    /// <summary>
    /// Fires once before every attack the owning creature makes.
    /// Performs the whole-attack critical roll and resets per-hit state.
    /// </summary>
    public override Task BeforeAttack(AttackCommand command)
    {
        if (command.Attacker != Owner)
            return Task.CompletedTask;

        ShionCritSystem.StartAttack(Owner.CombatState!, command.ModelSource as CardModel);
        return Task.CompletedTask;
    }

    /// <summary>
    /// Applies the 1.5× critical multiplier per damage-calculation call.
    /// Performs the per-hit crit roll on the first call for each hit (idempotent
    /// for additional AOE targets), then returns the multiplier.
    ///
    /// This fires for any attack the owning creature makes, covering both the
    /// character's own cards and any neutral cards they play.
    /// </summary>
    public override decimal ModifyDamageMultiplicative(
        Creature? target, decimal amount, ValueProp props, Creature? dealer, CardModel? cardSource)
    {
        if (dealer != Owner)
            return 1m;

        ShionCritSystem.EnsureHitRolled(Owner.CombatState!, cardSource);
        return ShionCritSystem.CurrentHitIsCrit ? 1.5m : 1m;
    }

    /// <summary>
    /// Plays critical-hit SFX / spawns gold VFX when a crit connects, then
    /// resets the per-hit roll guard so the next hit gets an independent roll.
    /// </summary>
    public override Task AfterDamageGiven(
        PlayerChoiceContext choiceContext, Creature? dealer, DamageResult result,
        ValueProp props, Creature target, CardModel? cardSource)
    {
        if (dealer != Owner) return Task.CompletedTask;
        if (ShionCritSystem.CurrentHitIsCrit && result.UnblockedDamage > 0)
        {
            // TODO: replace with real FMOD event / VFX scene paths once assets are ready.
            // SfxCmd.Play("event:/sfx/characters/shion/crit_hit");
            // VfxCmd.PlayOnCreatureCenter(target, "vfx/vfx_crit");
        }

        ShionCritSystem.EndHit();

        return Task.CompletedTask;
    }

    /// <summary>
    /// Fully resets crit state after the entire attack sequence finishes.
    /// </summary>
    public override Task AfterAttack(PlayerChoiceContext choiceContext, AttackCommand command)
    {
        if (command.Attacker == Owner)
            ShionCritSystem.EndAttack();

        return Task.CompletedTask;
    }
}

using MegaCrit.Sts2.Core.Commands.Builders;
using MegaCrit.Sts2.Core.Entities.Creatures;
using MegaCrit.Sts2.Core.GameActions.Multiplayer;
using MegaCrit.Sts2.Core.Localization.DynamicVars;
using MegaCrit.Sts2.Core.Models;
using MegaCrit.Sts2.Core.ValueProps;
using ShionTheBruiser.ShionTheBruiserCode.Critical;
using ShionTheBruiser.ShionTheBruiserCode.Variables;

namespace ShionTheBruiser.ShionTheBruiserCode.Powers;

/// <summary>
/// Internal tracker power that drives Shion's Critical Damage system.
///
/// This power is applied automatically to any creature whose combat-active
/// models include at least one <see cref="Critical.ICritHitRateContributor"/>,
/// <see cref="Critical.ICritAttackRateContributor"/>, or the minimum-rate
/// equivalents. It is applied via
/// <see cref="Critical.CritContributorPower.BeforeCombatStart"/> or
/// <see cref="Critical.CritContributorRelic.BeforeCombatStart"/>, so it
/// activates for <em>any</em> character that holds a crit contributor —
/// not just Shion.
///
/// Because it is a <see cref="MegaCrit.Sts2.Core.Entities.Powers.PowerStackType.Single"/>
/// power, repeated application is a no-op; exactly one instance exists per
/// creature per combat.
/// </summary>
public class ShionCritTrackerPower : ShionTheBruiserPower
{
    public override MegaCrit.Sts2.Core.Entities.Powers.PowerType Type =>
        MegaCrit.Sts2.Core.Entities.Powers.PowerType.Buff;

    public override MegaCrit.Sts2.Core.Entities.Powers.PowerStackType StackType =>
        MegaCrit.Sts2.Core.Entities.Powers.PowerStackType.Single;

    // ── DynamicVars ───────────────────────────────────────────────────────────

    /// <summary>
    /// Exposes the live crit rates as lazily-computed tokens for the smart description.
    /// <c>{HitRate}</c>    → per-hit critical chance as a whole integer percentage.
    /// <c>{AttackRate}</c> → whole-attack critical chance as a whole integer percentage.
    /// Both include the minimum-rate floor and are computed fresh on every hover-tip render.
    /// </summary>
    protected override IEnumerable<DynamicVar> CanonicalVars =>
    [
        new CritRateDisplayVar(isAttackRate: false),  // {HitRate}
        new CritRateDisplayVar(isAttackRate: true),   // {AttackRate}
    ];

    // ── Combat hooks ─────────────────────────────────────────────────────────

    /// <summary>
    /// Fires once before every attack the owning creature makes.
    /// Performs the whole-attack critical roll and resets per-hit state.
    /// </summary>
    public override Task BeforeAttack(AttackCommand command)
    {
        MainFile.Logger.Info($"[ShionCritTrackerPower] BeforeAttack fired. Attacker={command.Attacker?.GetType().Name ?? "null"}, Owner={Owner?.GetType().Name ?? "null"}, isMatch={command.Attacker == Owner}, ModelSource={command.ModelSource?.GetType().Name ?? "null"}");

        if (command.Attacker != Owner)
            return Task.CompletedTask;

        var card = command.ModelSource as CardModel;
        MainFile.Logger.Info($"[ShionCritTrackerPower] Calling StartAttack. Card={card?.GetType().Name ?? "null (no card)"}");
        ShionCritSystem.StartAttack(Owner.CombatState!, card);
        return Task.CompletedTask;
    }

    /// <summary>
    /// Applies the 1.5× critical multiplier per damage-calculation call.
    /// Performs the per-hit crit roll on the first call for each hit (idempotent
    /// for additional AOE targets), then returns the multiplier.
    ///
    /// This fires for any attack the owning creature makes, covering both the
    /// character's own cards and any neutral cards they play.
    /// </summary>
    public override decimal ModifyDamageMultiplicative(
        Creature? target, decimal amount, ValueProp props, Creature? dealer, CardModel? cardSource)
    {
        MainFile.Logger.Info($"[ShionCritTrackerPower] ModifyDamageMultiplicative fired. dealer={dealer?.GetType().Name ?? "null"}, Owner={Owner?.GetType().Name ?? "null"}, isMatch={dealer == Owner}, card={cardSource?.GetType().Name ?? "null"}");

        if (dealer != Owner)
            return 1m;

        ShionCritSystem.EnsureHitRolled(Owner.CombatState!, cardSource);
        decimal multiplier = ShionCritSystem.CurrentHitIsCrit ? 1.5m : 1m;
        MainFile.Logger.Info($"[ShionCritTrackerPower] CurrentHitIsCrit={ShionCritSystem.CurrentHitIsCrit}, returning multiplier={multiplier}");
        return multiplier;
    }

    /// <summary>
    /// Plays critical-hit SFX / spawns gold VFX when a crit connects, then
    /// resets the per-hit roll guard so the next hit gets an independent roll.
    /// </summary>
    public override Task AfterDamageGiven(
        PlayerChoiceContext choiceContext, Creature? dealer, DamageResult result,
        ValueProp props, Creature target, CardModel? cardSource)
    {
        if (dealer != Owner) return Task.CompletedTask;
        if (ShionCritSystem.CurrentHitIsCrit && result.UnblockedDamage > 0)
        {
            // TODO: replace with real FMOD event / VFX scene paths once assets are ready.
            // SfxCmd.Play("event:/sfx/characters/shion/crit_hit");
            // VfxCmd.PlayOnCreatureCenter(target, "vfx/vfx_crit");
        }

        ShionCritSystem.EndHit();

        return Task.CompletedTask;
    }

    /// <summary>
    /// Fully resets crit state after the entire attack sequence finishes.
    /// </summary>
    public override Task AfterAttack(PlayerChoiceContext choiceContext, AttackCommand command)
    {
        if (command.Attacker == Owner)
            ShionCritSystem.EndAttack();

        return Task.CompletedTask;
    }
}
